def bellman_ford(n, edges, src=0):
    """edges: list of (u, v, w). Returns dist, or None if neg-cycle from src."""
    INF = 10**18
    dist = [INF] * n
    dist[src] = 0

    # n−1 rounds — longest simple path has ≤ n−1 edges
    for _ in range(n - 1):
        updated = False
        for u, v, w in edges:
            if dist[u] != INF and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                updated = True
        if not updated:
            break  # early exit

    # nth pass — still improving ⇒ negative cycle
    for u, v, w in edges:
        if dist[u] != INF and dist[u] + w < dist[v]:
            return None  # or [-1] * n

    return dist

