def bellman_ford(n, edges, src=0):
    INF = 10**18
    dist = [INF] * n
    dist[src] = 0

    for _ in range(n - 1):
        updated = False
        for u, v, w in edges:
            if dist[u] != INF and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                updated = True
        if not updated:
            break

    for u, v, w in edges:
        if dist[u] != INF and dist[u] + w < dist[v]:
            return [-1]  # negative cycle

    return [(-1 if d >= INF else d) for d in dist]

