#include <bits/stdc++.h>
using namespace std;

// returns dist; empty vector means negative cycle from src
vector<long long> bellman_ford(int n, vector<array<int,3>>& edges, int src = 0) {
    const long long INF = 1e18;
    vector<long long> dist(n, INF);
    dist[src] = 0;

    for (int i = 0; i < n - 1; i++) {
        bool updated = false;
        for (auto [u, v, w] : edges) {
            if (dist[u] != INF && dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                updated = true;
            }
        }
        if (!updated) break;
    }

    for (auto [u, v, w] : edges) {
        if (dist[u] != INF && dist[u] + w < dist[v]) {
            return {}; // negative cycle
        }
    }
    return dist;
}
